// Hindi for sages/vyasa.js — keys are HI.hash(<Telugu string>). Written by tools/hi_write.js.
HI.add({
 "17391152": "“बेटा!” — और पेड़ों ने जवाब दिया",
 "42190396": "राजसूय के बाद एक चेतावनी",
 "52202426": "व्यास के पुत्र, जो अरणि (यज्ञ की अग्नि जलाने वाली लकड़ियों) से जन्मे और जन्म से ही मोह से मुक्त थे; उन्होंने राजा परीक्षित को भागवत सुनाई।",
 "54028240": "महाभारत, आश्रमवासिक पर्व — कुंती का अपना रहस्य खोलना, मरे हुए योद्धाओं का गंगा से उठना, विधवाओं का विदा होना, और जनमेजय का परीक्षित को देखना (पुत्रदर्शन खंड); जंगल की आग (नारदागमन खंड)। मौसल पर्व — ग्वालों के हाथों अर्जुन की हार और काल के बारे में व्यास के वचन (अंतिम अध्याय)।",
 "88987951": "द्रोण के पुत्र, जो माथे पर मणि लेकर जन्मे; युद्ध के बाद उन्होंने सोते हुए पांडव शिविर में लोगों को मार डाला और उन्हें धरती पर भटकते रहने का श्राप मिला।",
 "39cfb06f": "द्वीप पर जन्म — सत्यवती और पराशर",
 "de8633de": "व्यास की कहानी उनके जन्म से पहले ही शुरू हो जाती है — उनकी माँ से। चेदि देश में {uparichara|उपरिचर वसु} नाम के एक राजा राज करते थे। वे इंद्र को इतने प्यारे थे कि इंद्र ने उन्हें स्फटिक का एक रथ दिया जो आकाश में चलता था; इसीलिए उन्हें उपरिचर, यानी “ऊपर चलने वाला” कहा गया। वसंत के एक दिन वे शिकार पर गए, और उनकी रानी गिरिका घर पर उनकी राह देख रही थीं। फूलों से भरे वन में उन्हें रानी की बड़ी याद आई, और उनका वीर्य गिर गया। वह व्यर्थ न जाए, इसलिए उन्होंने उसे एक पत्ते में लपेटा और एक बाज़ को दिया कि वह उसे रानी तक पहुँचा दे।",
 "85afcdec": "रास्ते में एक दूसरे बाज़ ने यह सोचकर उस पर झपट्टा मारा कि इसमें मांस है। छीना-झपटी में वह पोटली यमुना में गिर गई। वहाँ उसे एक मछली निगल गई — जो असल में {adrika|अद्रिका} नाम की एक अप्सरा थी और श्राप के कारण मछली बनकर रह रही थी। कुछ महीनों बाद मछुआरों ने वह मछली पकड़ी, उसे चीरा, तो उसके भीतर एक बालक और एक बालिका मिले। अद्रिका श्राप से छूट गई और स्वर्ग चली गई।",
 "0a021a04": "मछुआरे उन जुड़वाँ बच्चों को राजा के पास ले गए। राजा ने लड़के को अपने पास रखा, जो बड़ा होकर राजा मत्स्य बना। लड़की उन्होंने {dasharaja|मछुआरों के मुखिया} को दे दी कि वह उसे अपनी बेटी की तरह पाले। वह साँवली और सुंदर थी, और उसका नाम {kurusatyavati|सत्यवती} रखा गया। पर मछली से जन्म लेने के कारण उसके शरीर से मछली की गंध आती थी, इसलिए लोग उसे मत्स्यगंधा — “मछली की गंध वाली” — कहते थे।",
 "5bb9ad59": "यमुना की नाव",
 "d67290f2": "अपने पिता की मदद के लिए किशोरी सत्यवती नाव चलाती थी और यात्रियों को यमुना पार कराती थी। एक दिन तीर्थयात्रा पर निकले एक महान ऋषि किनारे पर आए और उसकी नाव में बैठे। वे वसिष्ठ के पोते {parashara|पराशर} थे। नदी के बीच पहुँचकर वे उसकी सुंदरता पर मोहित हो गए और उससे साथ रहने की इच्छा जताई।",
 "41d5f92a": "सत्यवती डर गई। “दोनों किनारों पर ऋषि खड़े हैं, वे हमें देख रहे हैं,” उसने कहा। तब पराशर ने अपनी शक्ति से नदी को घने कोहरे से ढक दिया। फिर उसने कहा, “मैं अपने पिता के घर रहने वाली कुँवारी लड़की हूँ। अगर मेरा कौमार्य चला गया, तो मैं घर कैसे लौटूँगी? कैसे जिऊँगी?” पराशर ने वचन दिया कि उसके बाद भी वह कुँवारी ही रहेगी। और उसके माँगने पर उन्होंने उसे एक वरदान दिया: मछली की गंध उसके शरीर से हमेशा के लिए चली गई, और उसकी जगह उससे ऐसी मनमोहक सुगंध आने लगी जो एक योजन दूर तक महसूस होती थी। तब से उसे गंधवती, “सुगंध वाली”, और योजनगंधा कहा जाने लगा।",
 "bc0a315f": "महाभारत यह बात सीधे-सीधे बताता है — कि यह ऋषि की इच्छा और उसकी सहमति से हुआ — और इसे छिपाता नहीं। बाद में, रानी बनने पर, सत्यवती खुद यह रहस्य भीष्म को बताएँगी — और उनके बताने से कुरुओं का पूरा इतिहास बदल जाएगा।",
 "e552b66c": "द्वीप का साँवला बालक",
 "e7f4cf2d": "यमुना के बीच एक छोटे-से द्वीप पर सत्यवती ने उसी दिन एक पुत्र को जन्म दिया। जैसा पुरानी कहानियों में महान ऋषियों के बच्चों के साथ कभी-कभी होता है, वह बालक तुरंत बड़ा होकर युवक बन गया। वह बादल जैसा साँवला था, इसलिए उसे कृष्ण, यानी “साँवला” कहा गया; और द्वीप पर जन्म लेने के कारण उसे द्वैपायन कहा गया। इस तरह उसका पहला नाम था {vyasa|कृष्ण द्वैपायन}। बहुत बाद में, जब उन्होंने वेदों को व्यवस्थित किया, तो दुनिया ने उन्हें वेद व्यास कहा।",
 "57378fec": "युवा ऋषि ने अपनी माँ को प्रणाम किया और कहा: “मैं तपस्या करने वन जा रहा हूँ। पर जब भी आपको मेरी ज़रूरत हो और आप मुझे याद करें, मैं आ जाऊँगा।” फिर वे अपने पिता के साथ चले गए। सत्यवती फिर से कुँवारी और सुगंधित होकर मछुआरों के मुखिया के घर लौट आई, और यह रहस्य अपने दिल में छिपाए रखा।",
 "327c9f31": "पुराण व्यास को एक मनुष्य से कहीं बढ़कर मानते हैं। विष्णु पुराण कहता है कि कृष्ण द्वैपायन स्वयं नारायण हैं — वह पूछता है, उनके सिवा और कौन महाभारत रच सकता था? भागवत अपने पहले स्कंध में उन्हें भगवान के अवतारों में गिनता है, जो सत्यवती और पराशर से वेद रूपी वृक्ष को शाखाओं में बाँटने के लिए जन्मे।",
 "d55f2403": "उन्होंने तपस्या कहाँ की? परंपरा उन्हें हिमालय में, बदरी में, अलकनंदा के उद्गम के पास बेर (बदरी) के पेड़ों के बीच याद करती है। इसीलिए उनका एक नाम बादरायण है, यानी “बदरी वन वाले”। बद्रीनाथ से ऊपर माणा गाँव के पास एक छोटी गुफा आज भी यात्रियों को व्यास गुफा के रूप में दिखाई जाती है।",
 "540803db": "पराशर का जन्म कैसे हुआ और वसिष्ठ ने उनका क्रोध कैसे शांत किया",
 "8b3279be": "महाभारत, आदि पर्व (अंशावतरण खंड) — अद्रिका मछली से सत्यवती का और यमुना के द्वीप पर व्यास का जन्म; सम्भव खंड में सत्यवती यह कहानी भीष्म को फिर से सुनाती हैं। विष्णु पुराण, तीसरा अंश, अध्याय 4; भागवत पुराण, पहला स्कंध, अध्याय 3 (अवतारों में व्यास)। माणा की व्यास गुफा तीर्थयात्रियों की परंपरा है।",
 "5e49b35c": "{kurusatyavati|सत्यवती} यमुना में एक मछली से जन्मीं और मछुआरों के मुखिया ने उन्हें पाला।",
 "065ce40c": "{parashara|पराशर} उनसे उनकी नाव पर मिले; उनका पुत्र एक द्वीप पर जन्मा — कृष्ण द्वैपायन।",
 "d30613ea": "उन्होंने अपनी माँ को वचन दिया: “जब ज़रूरत हो, मुझे याद करना, मैं आ जाऊँगा।”",
 "7a58f921": "व्यास वन चले गए, पर उन्होंने वचन दिया कि जब भी माँ बुलाएँगी, वे आएँगे। किसी से किया वादा पूरी ज़िंदगी निभाने का क्या मतलब होता है?",
 "a4b1b3a5": "वेद को बाँटने वाले",
 "818a5cf2": "पुराण कहते हैं कि शुरुआत में वेद एक ही था — मंत्रों, स्तुतियों और यज्ञ-विधियों का एक विशाल सागर, जो केवल याद के सहारे गुरु से शिष्य तक पहुँचता था। संसार के आरंभिक युगों में लोग लंबा जीते थे, उनका मन मज़बूत होता था, और एक शिष्य पूरे वेद को याद रख सकता था।",
 "ad3060db": "पर {vyasa|व्यास} ने आगे देखा और जाना कि कलियुग आने वाला है। उन्होंने देखा कि लोगों की उम्र छोटी होगी, उनकी याददाश्त और ताक़त घट जाएगी, और कोई एक व्यक्ति पूरे वेद को सँभाल नहीं पाएगा। अगर कुछ न किया गया, तो वेद खो जाएगा। इसलिए आने वाले समय के लोगों पर दया करके उन्होंने वेद को व्यवस्थित करने का काम शुरू किया।",
 "e4d6c5b6": "स्तुति के मंत्रों को उन्होंने ऋग्वेद में इकट्ठा किया। यज्ञ करते समय बोले जाने वाले मंत्रों को यजुर्वेद में इकट्ठा किया। गाकर पढ़े जाने वाले मंत्रों को सामवेद में इकट्ठा किया। और रोग दूर करने, रक्षा करने और रोज़मर्रा के जीवन के मंत्रों को अथर्ववेद में इकट्ठा किया। इसीलिए उन्हें व्यास कहा जाता है — “जो फैलाए, बाँटे और व्यवस्थित करे।”",
 "ec4849ff": "चार शिष्य, और एक पाँचवाँ",
 "1387ca5b": "फिर उन्होंने हर वेद एक-एक शिष्य को सौंपा, ताकि हर वेद की अपनी गुरु-परंपरा बने। {paila|पैल} को उन्होंने ऋग्वेद दिया। {vaishampayana|वैशंपायन} को यजुर्वेद दिया। {jaimini|जैमिनि} को सामवेद दिया। {sumantu|सुमंतु} को अथर्ववेद दिया। और सूत कथावाचक {romaharshana|रोमहर्षण} को उन्होंने इतिहास और पुराण — पुरानी कथाएँ और इतिहास — दिए, ताकि जो आम लोग वेद नहीं पढ़ सकते थे, वे भी उसका ज्ञान सुन सकें।",
 "1a414ebf": "इन शिष्यों ने अपने-अपने शिष्यों को पढ़ाया, और उन्होंने हर वेद को आगे और शाखाओं में बाँटा। जैसे एक बीज से एक विशाल पेड़ उगता है, वैसे ही एक वेद सैकड़ों शाखाओं में फैल गया, और हर शाखा को वेदपाठियों के किसी परिवार ने जीवित रखा। इनमें से कुछ शाखाएँ आज भी तेलुगु घरों में और पूरे भारत की पाठशालाओं में अक्षरशः पढ़ी जाती हैं।",
 "3384a495": "इन शाखाओं में से एक की अपनी एक प्रसिद्ध कहानी है: वैशंपायन के शिष्य याज्ञवल्क्य का अपने गुरु से झगड़ा हुआ; उन्होंने सीखा हुआ यजुर्वेद लौटा दिया और सूर्य से एक नया यजुर्वेद पाया — शुक्ल (“सफ़ेद”) यजुर्वेद। वह कहानी याज्ञवल्क्य के अपने जीवन में आती है।",
 "5aa80514": "अट्ठाईस व्यास",
 "6719b834": "विष्णु पुराण एक चौंकाने वाली बात भी बताता है: “व्यास” एक उपाधि भी है। वह कहता है कि हर द्वापर युग में भगवान व्यास का रूप लेकर उस युग के लिए वेद को फिर से बाँटते हैं। हमारे इस मन्वंतर में अट्ठाईस व्यास हो चुके हैं, और पहले वालों में वह वसिष्ठ, शक्ति और पराशर के नाम लेता है — जो कृष्ण द्वैपायन के परदादा, दादा और पिता थे। कृष्ण द्वैपायन अट्ठाईसवें हैं। और वही पुराण कहता है कि अगले व्यास होंगे द्रोण के पुत्र अश्वत्थामा।",
 "4a5ce706": "इसलिए आज जब हम “व्यास” कहते हैं, तो हमारा मतलब होता है द्वीप के वे साँवले ऋषि, सत्यवती के पुत्र। उन्होंने वेद लिखा नहीं — वेद तो सुना गया है (श्रुति), जिसे ऋषियों ने ध्यान में देखा। उन्होंने उसे इकट्ठा किया, क्रम में लगाया और आगे सौंपा, ताकि वह बचा रहे। तब से हर वेदपाठ, एक तरह से, उन्हीं का उपहार है।",
 "5fa7f804": "विष्णु पुराण, तीसरा अंश, अध्याय 3–4 (अट्ठाईस व्यास; पैल, वैशंपायन, जैमिनि, सुमंतु और रोमहर्षण में वेद का बँटवारा); भागवत पुराण, पहला स्कंध, अध्याय 4, और बारहवाँ स्कंध, अध्याय 6।",
 "fb117303": "{vyasa|व्यास} ने देखा कि कलियुग के लोग पूरा वेद याद नहीं रख पाएँगे, इसलिए उन्होंने उसे चार भागों में बाँट दिया।",
 "3c0861fc": "{paila|पैल}, {vaishampayana|वैशंपायन}, {jaimini|जैमिनि} और {sumantu|सुमंतु} को चार वेद मिले; {romaharshana|रोमहर्षण} को पुराण।",
 "8538abaf": "विष्णु पुराण अट्ठाईस व्यास गिनाता है; कृष्ण द्वैपायन अट्ठाईसवें हैं।",
 "44d877ad": "व्यास ने अपना सबसे बड़ा काम उन लोगों के लिए किया जो अभी पैदा भी नहीं हुए थे। तुम आज ऐसा क्या कर सकते हो जो सौ साल बाद किसी के काम आए?",
 "44381a40": "मिटते वंश के लिए तीन पुत्र",
 "f766443f": "साल बीत गए। हस्तिनापुर के राजा {shantanu|शांतनु} यमुना के किनारे शिकार करते हुए एक अद्भुत सुगंध से खिंचे चले गए और मछुआरे की बेटी {kurusatyavati|सत्यवती} तक पहुँचे। वे उससे विवाह करना चाहते थे। उसके पिता एक शर्त पर राज़ी हुए: शांतनु के बाद सत्यवती का पुत्र ही राजा बनेगा। शांतनु के पुत्र देवव्रत ने पिता को खुश करने के लिए सिंहासन छोड़ दिया — और फिर, ताकि उनकी अपनी संतान कभी उस पर दावा न कर सके, कभी विवाह न करने की प्रतिज्ञा की। देवताओं ने फूल बरसाए और उन्हें {bhishma|भीष्म}, यानी “भीषण प्रतिज्ञा करने वाले” कहा।",
 "786e914e": "सत्यवती रानी बनीं और उनके दो पुत्र हुए। बड़े, चित्रांगद, कम उम्र में ही उसी नाम के एक गंधर्व से युद्ध में मारे गए। छोटे, {vichitravirya|विचित्रवीर्य}, राजा बने। भीष्म उनके लिए काशी की दो राजकुमारियाँ, {ambika|अंबिका} और {ambalika|अंबालिका}, जीतकर लाए। पर विचित्रवीर्य को क्षय रोग हो गया और वे जवानी में ही, बिना संतान के, चल बसे।",
 "06742386": "अब महान कुरु वंश का कोई उत्तराधिकारी नहीं था। सत्यवती ने भीष्म से विनती की कि वे विधवा रानियों से विवाह कर लें, या नियोग से उन्हें पुत्र दें — यह एक पुरानी प्रथा थी, जिसमें संतानहीन विधवा किसी चुने हुए पुरुष से पुत्र पा सकती थी, और वह पुत्र उसके पति का ही माना जाता था। भीष्म ने मना कर दिया: “मैं तीनों लोक छोड़ दूँगा, पर अपना वचन नहीं तोड़ूँगा।”",
 "95b414d7": "माँ को याद आया",
 "4d701453": "तब सत्यवती ने कुछ झिझक और कुछ आशा के साथ भीष्म को वह रहस्य बताया जो उन्होंने जीवन भर छिपाए रखा था: नाव, कोहरा, ऋषि पराशर, और द्वीप पर जन्मा पुत्र। “वे एक महान ऋषि हैं, कृष्ण द्वैपायन, जिन्होंने वेद को बाँटा,” उन्होंने कहा। “उन्होंने वचन दिया था कि जब मैं उन्हें याद करूँगी, वे आएँगे। तुम मान जाओ, तो मैं उन्हें बुलाऊँ।” भीष्म ने हाथ जोड़े: “माँ, यही सही रास्ता है।”",
 "ca04511c": "सत्यवती ने अपने पुत्र को याद किया, और व्यास अपने वचन के अनुसार उसी पल प्रकट हो गए। उन्होंने रोते हुए उन्हें गले लगाया और कहा कि वे अपने भाई की विधवाओं को पुत्र दें। माँ के प्रति कर्तव्य मानकर व्यास राज़ी हो गए। पर उन्होंने कहा कि रानियाँ तैयार होने के लिए पहले एक साल का व्रत करें। “समय नहीं है,” सत्यवती ने कहा। “बिना राजा का राज्य बिखर जाता है।” “तो फिर,” व्यास बोले, “वे मेरे रूप को सह लें। यही उनका व्रत होगा।”",
 "dc6ad436": "क्योंकि व्यास सीधे वन की तपस्या से आए थे: साँवले, दुबले-पतले, भूरी जटाएँ, खुरदुरी दाढ़ी, दहकती आँखें, और शरीर से जंगल की गंध। काशी की युवा रानियों ने ऐसा कोई व्यक्ति पहले कभी नहीं देखा था।",
 "6861ef14": "अंधा, पीला और ज्ञानी",
 "45d33583": "जब व्यास अंबिका के पास गए, तो वह उनका चेहरा देखकर इतनी डर गई कि उसने आँखें बंद कर लीं और बंद ही रखीं। बाद में व्यास ने सत्यवती से कहा: “इसका पुत्र दस हज़ार हाथियों जितना बलवान, एक बुद्धिमान राजा और सौ पुत्रों का पिता होगा। पर क्योंकि उसकी माँ ने आँखें बंद कर ली थीं, वह अंधा पैदा होगा।” और इस तरह {dhritarashtra|धृतराष्ट्र} अंधे पैदा हुए।",
 "5044df85": "“अंधा व्यक्ति राजा नहीं बन सकता,” सत्यवती ने कहा, और व्यास से अंबालिका के पास जाने को कहा। अंबालिका ने आँखें तो बंद नहीं कीं, पर डर से उसका रंग पीला पड़ गया। “इसका पुत्र पीला होगा,” व्यास ने कहा, “और यही उसका नाम होगा।” इस तरह {pandu|पांडु}, यानी “पीले रंग वाले”, जन्मे — वीर और बलवान, आगे चलकर पांडवों के पिता।",
 "62584d1d": "सत्यवती ने अंबिका से एक और पुत्र माँगा। पर अंबिका को उनका चेहरा याद आया और वह जाने की हिम्मत नहीं जुटा पाई। उसने अपनी एक दासी को अपने गहने पहनाकर उसकी जगह भेज दिया। दासी डरी नहीं। उसने उठकर ऋषि का स्वागत किया, आदर से उनकी सेवा की और उनसे प्रेम से पेश आई। व्यास प्रसन्न हुए। “आज से तुम दासता से मुक्त हो,” उन्होंने उससे कहा। “तुम्हारा पुत्र धरती का सबसे ज्ञानी व्यक्ति होगा।” वह पुत्र थे {vidura|विदुर}। व्यास ने सत्यवती को बताया कि अंबिका ने क्या किया था, और वन लौट गए।",
 "d353fb9f": "विदुर धर्मराज क्यों थे",
 "4e7745ee": "महाभारत बताता है कि विदुर असल में धर्म के देवता, धर्मराज थे, जो एक श्राप के कारण मनुष्य बनकर जन्मे। {mandavya|मांडव्य} नाम के एक मौनव्रती ऋषि को एक बार ग़लती से उन चोरों के साथ पकड़ लिया गया जो उनके आश्रम में छिपे थे, और राजा के सिपाहियों ने उन्हें सूली पर चढ़ा दिया। वे मरे नहीं। बाद में जब उन्होंने धर्मराज से पूछा कि किस पाप की उन्हें ऐसी सज़ा मिली, तो धर्मराज ने कहा: “बचपन में तुमने एक कीड़े को घास के तिनके से छेदा था।” मांडव्य को क्रोध आया: “तुमने एक बच्चे की नासमझी को बड़े आदमी के अपराध जैसा दंड दिया। तुम धरती पर एक दासी के पुत्र बनकर मनुष्य के रूप में जन्म लो!” उन्होंने यह नियम भी बनाया कि चौदह साल की उम्र से पहले किया गया कोई काम पाप नहीं गिना जाएगा।",
 "fbfced83": "इस तरह व्यास के तीनों पुत्र भीष्म की देखरेख में साथ-साथ बड़े हुए: अंधे धृतराष्ट्र, पीले पांडु और ज्ञानी विदुर। वन के ऋषि व्यास अब कौरवों और पांडवों — दोनों के दादा बन गए थे — उन्हीं दो परिवारों के, जिनके युद्ध की कथा वे एक दिन महाभारत में सुनाने वाले थे।",
 "961494f8": "नियोग एक पुरानी प्रथा थी, जिसका वर्णन महाभारत और शुरुआती धर्मशास्त्रों में मिलता है; जब पति की मृत्यु हो जाए या वह संतान न दे सके, तब वंश को आगे बढ़ाने के लिए इसका सहारा लिया जाता था। बाद के धर्मशास्त्र, जैसे मनुस्मृति, कलियुग के लिए इसे ठीक नहीं मानते या मना करते हैं। महाभारत इसे बिना किसी शर्म के बताता है, क्योंकि उसके लिए वंश के प्रति कर्तव्य सबसे पहले था।",
 "26b7a2da": "महाभारत, आदि पर्व (सम्भव खंड) — सत्यवती और शांतनु, भीष्म की प्रतिज्ञा, विचित्रवीर्य की मृत्यु, सत्यवती का रहस्य, और धृतराष्ट्र, पांडु और विदुर का जन्म (क्रिटिकल एडिशन में अध्याय 94–100); अणी-मांडव्य की कथा इसके बाद आती है (अध्याय 101 और आगे)।",
 "d1bd5e2e": "जब कुरु वंश का कोई उत्तराधिकारी नहीं रहा, तब {kurusatyavati|सत्यवती} ने {bhishma|भीष्म} को अपना रहस्य बताया और व्यास को बुलाया।",
 "d9b12ede": "{ambika|अंबिका} ने आँखें बंद कर लीं, इसलिए {dhritarashtra|धृतराष्ट्र} अंधे पैदा हुए; {ambalika|अंबालिका} पीली पड़ गई, इसलिए {pandu|पांडु} पीले थे।",
 "8fc69b50": "निडर दासी {vidura|विदुर} की माँ बनी, जो स्वयं धर्मराज थे।",
 "3bd9635d": "दो रानियाँ व्यास से डर के साथ मिलीं, और एक दासी आदर के साथ। उसी का पुत्र सबसे ज्ञानी बना। जब हम किसी अनजान व्यक्ति से डर की जगह आदर से मिलते हैं, तो क्या बदल जाता है?",
 "3bdf69b0": "गांधारी के सौ पुत्र — और सत्यवती की विदाई",
 "c3fcbc93": "धृतराष्ट्र का विवाह गांधार की राजकुमारी {gandhari|गांधारी} से हुआ, जिन्होंने अपने पति के न देख पाने के कारण जीवन भर के लिए अपनी आँखों पर पट्टी बाँध ली। एक दिन व्यास भूख और लंबे रास्ते से थके-माँदे हस्तिनापुर आए। गांधारी ने बड़े प्रेम से उनकी सेवा की। प्रसन्न होकर उन्होंने उन्हें वरदान माँगने को कहा, और गांधारी ने अपने पति जैसे बलवान सौ पुत्र माँगे। “ऐसा ही हो,” व्यास ने कहा।",
 "413d8a28": "गांधारी गर्भवती हुईं — पर बच्चा पैदा नहीं हुआ। एक साल बीता, फिर दो। इसी बीच वन से खबर आई कि पांडु की पत्नी {kunti|कुंती} ने सुबह के सूरज जैसे तेजस्वी पुत्र {yudhishthira|युधिष्ठिर} को जन्म दिया है। गांधारी दुख और ईर्ष्या से भर गईं। पति को बताए बिना उन्होंने अपने पेट पर ज़ोर से प्रहार किया। जो बाहर आया वह बच्चा नहीं, बल्कि लोहे के गोले जैसा मांस का एक सख़्त पिंड था।",
 "47f945d1": "वे उसे फेंकने ही वाली थीं कि व्यास आ पहुँचे। “सुबल की बेटी, तुमने यह क्या किया?” उन्होंने पूछा। गांधारी ने सच बता दिया: “आपने मुझे सौ पुत्रों का वचन दिया था, और देखिए क्या पैदा हुआ है।” “मेरी बात आज तक एक बार भी झूठी नहीं हुई,” व्यास ने कहा, “मज़ाक में भी नहीं।”",
 "875c76bb": "एक सौ एक घड़े",
 "fc9559b2": "उन्होंने घी से भरे सौ घड़े एक छिपी हुई, ठंडी जगह में रखवाए। उन्होंने मांस के उस पिंड पर ठंडा पानी छिड़कवाया, और वह अँगूठे के पोर जितने टुकड़ों में बँट गया। जब उन्हें गिना जा रहा था, गांधारी ने धीरे से कहा, “मुझे एक बेटी भी चाहिए।” इसलिए एक सौ एक टुकड़े हुए, और एक घड़ा और लाया गया। व्यास ने कहा कि घड़ों को सही समय पूरा होने के बाद ही खोला जाए, और हिमालय में अपनी तपस्या के लिए लौट गए।",
 "161bdfca": "समय आने पर पहला घड़ा खुला, और उसमें से {duryodhana|दुर्योधन} निकले। उसी पल सियार हुआँ-हुआँ करने लगे, गधे रेंकने लगे, और कई जगह आग लग गई। विदुर और ज्ञानी ब्राह्मणों ने धृतराष्ट्र को चेताया: “ये भयानक अपशकुन हैं। कुल और संसार की भलाई के लिए इस बच्चे को त्याग दीजिए।” पर पिता का मोह बहुत गहरा था; वे ऐसा नहीं कर सके। फिर बाकी निन्यानवे पुत्र जन्मे, और सबसे आख़िर में बेटी {duhshala|दुःशला}। धृतराष्ट्र का महल की एक दासी से एक और पुत्र भी था — युयुत्सु।",
 "85f0ebd4": "महाभारत कहता है कि दुर्योधन उसी दिन जन्मे जिस दिन दूसरे पांडव भीम। कह सकते हैं कि दोनों सबसे बलवान चचेरे भाइयों की दुश्मनी उनके पहले ही दिन से शुरू हो गई थी।",
 "20d60d5c": "“अच्छे दिन बीत गए”",
 "8d2a4fee": "बरसों बाद पांडु की वन में मृत्यु हो गई, और कुंती पाँचों छोटे पांडवों को लेकर हस्तिनापुर आईं। पांडु के अंतिम संस्कार के बाद व्यास अपनी माँ {kurusatyavati|सत्यवती} के पास आए, जो दुख में डूबी थीं। उन्होंने कोमलता से, पर सच-सच कहा: “माँ, सुख के दिन बीत गए। भयानक दिन आने वाले हैं। धरती का यौवन ढल चुका है। इन पोतों के बुरे कर्मों से कुरु वंश नष्ट हो जाएगा। यह सब देखने के लिए यहाँ मत रुकिए। वन जाइए और योग में मन लगाइए।”",
 "5dfd3ebf": "सत्यवती ने अपने पुत्र की बात मानी। वे अपनी दोनों बहुओं, {ambika|अंबिका} और {ambalika|अंबालिका}, को साथ लेकर गईं, और तीनों रानियाँ वन चली गईं। वहाँ उन्होंने तपस्या की, और समय आने पर देह त्यागकर उच्च लोकों को चली गईं। जो मछुआरे की बेटी कभी यमुना पार यात्रियों की नाव खेती थी, उसने अपने पुत्र की सलाह पर एक वनवासी तपस्विनी के रूप में अपना जीवन पूरा किया।",
 "c81a859b": "यहाँ हम पहली बार वह देखते हैं जो व्यास महाभारत में बार-बार करेंगे: वे जानते थे कि आगे क्या होने वाला है, वे उसके बारे में सच बोलते थे, फिर भी किसी पर ज़बरदस्ती नहीं करते थे। वे सलाह देते, चेताते, मदद करते — और फिर हर व्यक्ति को अपना रास्ता खुद चुनने देते।",
 "4290e0c8": "महाभारत, आदि पर्व (सम्भव खंड) — गांधारी का वरदान और सौ पुत्रों तथा दुःशला का जन्म (क्रिटिकल एडिशन में अध्याय 107–108); पांडु की मृत्यु के बाद सत्यवती को व्यास की सलाह (अध्याय 119)।",
 "c7521a32": "{gandhari|गांधारी} की सेवा से प्रसन्न होकर व्यास ने उन्हें सौ पुत्रों का वरदान दिया।",
 "9da93ddb": "उन्होंने मांस के पिंड को बाँटकर घी के एक सौ एक घड़ों में रखा — सबसे पहले {duryodhana|दुर्योधन}, सबसे आख़िर में {duhshala|दुःशला}।",
 "26fb582f": "उन्होंने अपनी माँ को वन भेज दिया ताकि उन्हें अपने परिवार का नाश न देखना पड़े।",
 "015f1986": "गांधारी की ईर्ष्या ने उनसे अपने ही शरीर पर प्रहार करवाया। ईर्ष्या किसी और को चोट पहुँचाने से पहले हमें कहाँ चोट पहुँचाती है?",
 "aeddd0e7": "वन में दादाजी — पांडवों के मार्गदर्शक",
 "cc8f7a18": "दुर्योधन ने पांडवों को मारने के लिए लाख का जो घर बनवाया था, उसकी आग से बचकर पांडव अपनी माँ {kunti|कुंती} के साथ वन में भाग गए — छिपते हुए, थके और डरे हुए। वहाँ उनके दादा व्यास उनके पास आए। कुंती रोते हुए उनके चरणों में गिर पड़ीं। “मैं यह सब जानता था,” उन्होंने उनसे कहा। “मेरे लिए तुम और धृतराष्ट्र के पुत्र बराबर हो; पर दादा का दिल कमज़ोर और अन्याय सहने वाले की ओर खिंचता है। दुखी मत हो। तुम्हारे लिए इस सबका अंत अच्छा होगा।”",
 "ddb86931": "वे उन्हें पास के नगर एकचक्रा ले गए और एक ब्राह्मण के घर में ठहरा दिया, जहाँ वे भिक्षा पर जीने वाले ब्राह्मण विद्यार्थियों के भेस में रहे। “यहीं मेरी राह देखना,” उन्होंने कहा, “जब तक मैं फिर न आऊँ।” एकचक्रा में ही बाद में भीम ने बक नाम के उस राक्षस को मारा, जो नगर के लोगों को खा रहा था।",
 "c521bd97": "द्रौपदी के पाँच पति क्यों थे",
 "93c76627": "द्रौपदी के स्वयंवर से पहले व्यास फिर आए और पांडवों को एक कहानी सुनाई। पिछले जन्म में एक ऋषि की बेटी को कोई पति नहीं मिल रहा था। उसने {shiva|शिव} की तपस्या की, और जब वे प्रकट हुए, तो उसने उतावलेपन में पाँच बार कहा, “मुझे सब गुणों वाला पति दीजिए।” “अगले जन्म में तुम्हारे पाँच पति होंगे,” शिव ने कहा। व्यास ने बताया कि वही लड़की अब द्रुपद की यज्ञ-अग्नि से {draupadi|द्रौपदी} के रूप में जन्मी है। “वह तुम्हारे लिए ही है। पांचाल जाओ।”",
 "6e7ad797": "स्वयंवर में अर्जुन ने उन्हें जीता, और कुंती ने बिना देखे बेटों से कहा कि जो लाए हो, आपस में बाँट लो। जब पाँचों भाई मिलकर द्रौपदी से विवाह करना चाहते थे, तो राजा {drupada|द्रुपद} हैरान रह गए: “एक स्त्री के कई पति? यह तो धर्म के विरुद्ध है।” व्यास दरबार में आए, द्रुपद को अलग ले गए और उन्हें गहरी कहानी सुनाई — उन पाँच इंद्रों की, जिन्हें अपने घमंड के कारण धरती पर पाँच पांडवों के रूप में जन्म लेना था, और लक्ष्मी की, जो उन सबकी पत्नी बनने के लिए द्रौपदी के रूप में जन्मीं। उन्होंने द्रुपद को एक पल के लिए दिव्य दृष्टि दी, और द्रुपद ने भाइयों को उनके असली, चमकते रूप में देखा। उनका संदेह दूर हो गया, और विवाह हो गया।",
 "82a00e3a": "जब {yudhishthira|युधिष्ठिर} ने इंद्रप्रस्थ में महान राजसूय यज्ञ किया, तो स्वयं व्यास मुख्य पुरोहित बने। अतिथियों के जाने के बाद युधिष्ठिर ने उनसे उन अजीब अपशकुनों के बारे में पूछा जो दिखाई दिए थे। व्यास ने दुखी होकर उत्तर दिया: “तेरह साल में ये संकेत अपना फल देंगे। उस समय के अंत में धरती के क्षत्रियों का नाश हो जाएगा — और इसका कारण तुम बनोगे, जबकि दुर्योधन के अन्याय और भीम और अर्जुन का बल इसके साधन होंगे।”",
 "fba651f7": "युधिष्ठिर हिल गए। उसी दिन उन्होंने एक व्रत लिया: तेरह साल तक वे किसी से कठोर बात नहीं कहेंगे, न अपने भाइयों से झगड़ेंगे न दूसरे राजाओं से, और हमेशा बड़ों की बात मानेंगे। व्रत अच्छा था — फिर भी, महाभारत इशारा करता है कि इसी कारण वे धृतराष्ट्र के जुए के निमंत्रण को ठुकरा नहीं सके।",
 "865c4e3e": "वनवास के दौरान सलाह",
 "fc9f0d3e": "जुए के खेल के कारण जब पांडवों को वनवास मिला, तो व्यास {dhritarashtra|धृतराष्ट्र} के पास गए और विनती की कि वे {duryodhana|दुर्योधन} को रोकें और सुलह कर लें। उन्होंने बताया कि सब गायों की माँ सुरभि एक बार स्वर्ग में इसलिए रोई थीं कि धरती पर उनके एक बेटे, एक कमज़ोर बैल, को पीटा जा रहा था — “माता-पिता का प्यार सबसे ज़्यादा उसी बच्चे की ओर जाता है जो दुख में हो। पांडु के बेटों के लिए भी वैसा ही महसूस करो।” धृतराष्ट्र ने बातों में हाँ कह दी, पर किया कुछ नहीं।",
 "6418b07e": "बाद में व्यास वन में पांडवों के पास आए और युधिष्ठिर को प्रतिस्मृति नाम की एक गुप्त विद्या सिखाई, जिसे {arjuna|अर्जुन} को देना था। उसके सहारे अर्जुन हिमालय गए, शिव से पाशुपत अस्त्र पाया, और देवताओं के अस्त्र सीखने इंद्र के स्वर्ग गए। वनवास के लंबे सालों में दादाजी बार-बार आते रहे, कहानियाँ सुनाकर उन्हें दिलासा देते रहे और उनकी आशा जगाए रखी।",
 "9d94074c": "महाभारत, आदि पर्व — व्यास पांडवों को एकचक्रा ले जाते हैं (हिडिंब-वध खंड); द्रौपदी का पिछला जन्म (चैत्ररथ खंड); पाँच इंद्र और द्रुपद को दर्शन (वैवाहिक खंड)। सभा पर्व — राजसूय में मुख्य पुरोहित के रूप में व्यास और तेरह साल की उनकी भविष्यवाणी (द्यूत खंड की शुरुआत)। आरण्यक (वन) पर्व — धृतराष्ट्र को सुनाई गई सुरभि की कथा, और युधिष्ठिर को दी गई प्रतिस्मृति।",
 "7adeb3d3": "लाख के घर की घटना के बाद व्यास ने पांडवों को एकचक्रा में छिपाया।",
 "16df2aa2": "उन्होंने {drupada|द्रुपद} को समझाया कि {draupadi|द्रौपदी} के पाँच पति क्यों होंगे।",
 "7539e647": "उन्होंने तेरह साल पहले ही युद्ध की भविष्यवाणी कर दी, और वह प्रतिस्मृति दी जिससे {arjuna|अर्जुन} दिव्य अस्त्र पाने गए।",
 "6ba9b0e6": "व्यास ने धृतराष्ट्र को चेताया, जिन्होंने हाँ तो कहा पर किया कुछ नहीं। अच्छी सलाह सही है यह जानते हुए भी उस पर चलना इतना कठिन क्यों होता है?",
 "ad841f5f": "संजय को आँखें — और दो महान अस्त्र",
 "f70aaa66": "कुरुक्षेत्र में दोनों सेनाएँ आमने-सामने खड़ी थीं। पहला बाण चलने से पहले व्यास हस्तिनापुर में अपने अंधे पुत्र {dhritarashtra|धृतराष्ट्र} के पास आए। “तुम्हारे पुत्रों और इन राजाओं का अंत आ गया है,” उन्होंने कहा। “अगर तुम युद्ध देखना चाहो, तो मैं तुम्हें दृष्टि दे दूँगा।” धृतराष्ट्र ने मना कर दिया: “मैं अपने ही परिवार को मरते नहीं देखना चाहता। पर उसकी हर बात सुनना चाहता हूँ।”",
 "fe8a8f76": "तब व्यास ने राजा के सारथी {sanjaya|संजय} को दिव्य दृष्टि दी। “संजय सब कुछ देखेगा,” उन्होंने कहा, “चाहे वह खुले में हो या छिपकर, दिन में हो या रात में — यहाँ तक कि लोग मन में क्या सोचते हैं, वह भी। कोई अस्त्र उसे चोट नहीं पहुँचाएगा, और वह इस युद्ध से जीवित निकलेगा।” फिर व्यास ने चारों ओर दिख रहे भयानक अपशकुनों का वर्णन किया, और आख़िरी बार शांति की विनती की। उसे किसी ने नहीं सुना।",
 "d507d459": "इसीलिए भगवद्गीता धृतराष्ट्र के इस प्रश्न से शुरू होती है, “संजय, मेरे पुत्रों और पांडु के पुत्रों ने क्या किया?” — और इसीलिए पूरी गीता हम तक संजय के शब्दों से पहुँचती है। व्यास के दिए दृष्टि के इस उपहार के बिना, रथ से दूर कोई भी कृष्ण को अर्जुन को उपदेश देते नहीं सुन सकता था।",
 "357d61aa": "आकाश में दो आग",
 "075e65c1": "अठारह दिन बाद युद्ध ख़त्म हो गया। उस रात द्रोण के पुत्र {ashvatthama|अश्वत्थामा} चुपके से सोते हुए पांडव शिविर में घुसे और द्रौपदी के पाँचों पुत्रों और बहुत-से दूसरे लोगों को सोते में ही मार डाला। सुबह पांडवों ने {krishna|कृष्ण} के साथ उनका पीछा किया और गंगा के किनारे तक पहुँचे, जहाँ वे व्यास के आश्रम के पास ऋषियों के बीच बैठे थे।",
 "1037a281": "उन्हें देखकर अश्वत्थामा ने घास का एक तिनका तोड़ा, उसमें भयानक ब्रह्मशिर अस्त्र की शक्ति भरी, और “पांडवों के नाश के लिए!” कहकर छोड़ दिया। कृष्ण ने {arjuna|अर्जुन} से उसका जवाब देने को कहा, और अर्जुन ने अपना ब्रह्मशिर छोड़ा, इस प्रार्थना के साथ कि वह केवल दूसरे अस्त्र को रोके। दोनों अस्त्र आकाश में प्रलय की आग की तरह धधक उठे।",
 "4fa61963": "तब {narada|नारद} और व्यास उनके बीच आ खड़े हुए — लोकों को बचाने के लिए दोनों आगों के बीचोंबीच। “बहुत-से महान योद्धा ये अस्त्र जानते थे,” उन्होंने कहा, “पर किसी ने कभी इन्हें मनुष्यों पर नहीं चलाया। इन्हें वापस लो।” अपने व्रतों में पवित्र अर्जुन ने तुरंत अपना अस्त्र वापस ले लिया। अश्वत्थामा ऐसा नहीं कर सके — उनमें उसे लौटाने लायक आत्मसंयम की शक्ति नहीं थी।",
 "6bd6b8c1": "“मैं इसे वापस नहीं बुला सकता,” अश्वत्थामा ने कहा, “पर इसकी दिशा मोड़ सकता हूँ।” और उन्होंने वह अस्त्र पांडव स्त्रियों के गर्भ की ओर मोड़ दिया, ताकि पांडवों का वंश ख़त्म हो जाए। वह अभिमन्यु की विधवा {uttara|उत्तरा} के गर्भ में पल रहे शिशु पर लगा। कृष्ण ने शांति से कहा: “वह बच्चा मरा हुआ जन्मेगा, और मैं उसे जीवित कर दूँगा।” वह बच्चा था {parikshit|परीक्षित}, यानी “जिसकी परीक्षा हुई”।",
 "9eb20631": "फिर कृष्ण ने अश्वत्थामा को श्राप दिया: तीन हज़ार साल तक वे धरती पर अकेले भटकेंगे, बीमार और बिना किसी साथी के, बिना किसी से बात किए। व्यास ने इस श्राप का समर्थन किया: “तुमने यह भयानक काम मेरे सामने खड़े-खड़े किया।” अश्वत्थामा ने जन्म से माथे पर लगी अपनी मणि दे दी और वन में चले गए। द्रौपदी ने वह मणि युधिष्ठिर को पहनने के लिए दे दी।",
 "56584af6": "गांधारी का क्रोध",
 "4077425e": "जब पांडव अपने सौ के सौ पुत्र खो चुकी {gandhari|गांधारी} को प्रणाम करने आए, तो वे युधिष्ठिर को श्राप देना चाहती थीं। व्यास उनके मन की बात जान गए और पहले ही आ गए। “याद करो,” उन्होंने कहा, “अठारह दिनों तक, जब दुर्योधन तुमसे आशीर्वाद माँगने आता था, तुम बस इतना ही कहती थीं: ‘जहाँ धर्म है, वहाँ विजय है।’ तुम्हारे शब्द सच हो गए। अब धर्म के पक्ष पर क्रोध मत करो।” गांधारी ने अपना श्राप रोक लिया — फिर भी उनकी आँखों की पट्टी के नीचे से पड़ी क्रोध भरी नज़र से युधिष्ठिर के पैरों के नाखून जलकर काले पड़ गए।",
 "bbc50aeb": "उसके बाद, जब युधिष्ठिर इतने दुखी थे कि राज्य छोड़कर वन जाना चाहते थे, तो व्यास भी उन लोगों में थे जिन्होंने उन्हें समझाया, पुराने राजाओं की कहानियाँ सुनाईं, और उन्हें बाणों की शय्या पर लेटे भीष्म से सीखने भेजा। बाद में उन्होंने युधिष्ठिर को बताया कि राजा मरुत्त ने हिमालय में सोने का बड़ा ख़ज़ाना कहाँ छोड़ा था, ताकि वे अश्वमेध यज्ञ करके देश के घाव भर सकें।",
 "c85c7b23": "महाभारत, भीष्म पर्व — व्यास संजय को दिव्य दृष्टि देते हैं (शुरुआती अध्याय, भगवद्गीता से पहले)। सौप्तिक पर्व — दो ब्रह्मशिर अस्त्र, उनके बीच नारद और व्यास, अश्वत्थामा को श्राप (अंतिम अध्याय)। स्त्री पर्व — व्यास गांधारी को रोकते हैं। शांति और आश्वमेधिक पर्व — व्यास युधिष्ठिर को सलाह देते हैं और उन्हें मरुत्त के सोने के बारे में बताते हैं।",
 "f3947956": "व्यास ने {sanjaya|संजय} को दिव्य दृष्टि दी, ताकि पूरा युद्ध — और गीता — {dhritarashtra|धृतराष्ट्र} को सुनाया जा सके।",
 "dc85d3cb": "{narada|नारद} के साथ वे दोनों ब्रह्मशिर अस्त्रों के बीच खड़े हुए; {arjuna|अर्जुन} ने अपना अस्त्र वापस ले लिया, {ashvatthama|अश्वत्थामा} नहीं ले सके।",
 "d8276885": "उन्होंने {gandhari|गांधारी} का क्रोध उन्हीं के शब्दों से शांत किया: “जहाँ धर्म है, वहाँ विजय है।”",
 "53bd3bc9": "अर्जुन अपना अस्त्र वापस ले सके; अश्वत्थामा नहीं ले सके। गुस्से में किया काम शुरू करना आसान और उसे वापस लेना इतना कठिन क्यों होता है?",
 "23147d8c": "गंगा किनारे एक रात — मरे हुए लौट आए",
 "c5efb622": "युद्ध के पंद्रह साल बाद बूढ़े {dhritarashtra|धृतराष्ट्र} अपने आख़िरी साल वन में बिताने के लिए हस्तिनापुर छोड़कर चले गए। {gandhari|गांधारी} उनके साथ गईं, और संजय, और {vidura|विदुर} भी। और विजयी पांडवों की माँ {kunti|कुंती} ने भी उनके साथ जाना चुना, ताकि सब कुछ खो चुके उस बूढ़े दंपती की सेवा कर सकें। उनके बेटों ने रुकने की बहुत विनती की; वे नहीं मानीं।",
 "579828bd": "जब पांडव वन में उनसे मिलने आए, तो उपवास से दुबले हो चुके विदुर ने योग से अपने प्राण त्याग दिए, और उनकी आत्मा {yudhishthira|युधिष्ठिर} में समा गई — क्योंकि दोनों धर्म से जन्मे थे। फिर व्यास आए। उन्होंने देखा कि धृतराष्ट्र, गांधारी और कुंती को अब भी शांति नहीं मिल रही; वे अब भी अपने पुत्रों के लिए दुखी थे। “आज रात,” उन्होंने कहा, “मैं तुम्हें एक चमत्कार दिखाऊँगा जो मेरी तपस्या से मिला है। जो चाहो, माँगो।”",
 "d7224860": "गांधारी ने अपने पुत्रों को एक बार फिर देखना चाहा। कुंती ने रोते हुए आख़िरकार {karna|कर्ण} का रहस्य खोल दिया — अपने पहले पुत्र का, जो उनके विवाह से पहले जन्मा था और जिसे उन्होंने नदी में बहा दिया था, और जो अपने ही भाइयों से लड़ते हुए मारा गया था। “मुझे उसे देखने दीजिए,” उन्होंने कहा। व्यास ने उन्हें दिलासा दिया: “यह तुम्हारा पाप नहीं था। यह देवताओं ने ही करवाया था।” और उन्होंने बताया कि जितने योद्धा मरे थे, वे सब देवताओं, असुरों और गंधर्वों के अंश थे, जो अपनी-अपनी भूमिका निभाने धरती पर आए थे और अब लौट चुके थे।",
 "ecb36aef": "नदी से उठी सेना",
 "3b759870": "उस शाम सब लोग गंगा के किनारे इकट्ठा हुए। व्यास पवित्र जल में उतरे और दोनों पक्षों के मरे हुए योद्धाओं को पुकारा। नदी से कुरुक्षेत्र की सेनाओं जैसी एक भारी गर्जना उठी। और पानी से वे निकल आए — भीष्म और द्रोण, कर्ण, दुर्योधन और उसके भाई, अभिमन्यु, द्रौपदी के पाँचों पुत्र, घटोत्कच, द्रुपद, विराट और हज़ारों और — हर कोई अपने कवच में, अपने ध्वज और रथ के साथ, देवताओं की तरह चमकता हुआ।",
 "48e1cc8b": "उस एक रात के लिए व्यास ने धृतराष्ट्र को दिव्य दृष्टि दी, और जीवन में पहली बार अंधे राजा ने अपने पुत्रों को देखा। किसी के मन में न क्रोध बचा था, न घमंड, न ईर्ष्या। दुश्मन दोस्तों की तरह मिले; पिता पुत्रों से मिले; पत्नियाँ पतियों से मिलीं; कुंती ने कर्ण को गले लगाया, और भाइयों ने उस भाई को गले लगाया जिसे उन्होंने मारा था। पूरी रात वे साथ रहे, खुश, जैसे स्वर्ग में हों।",
 "91d2a6ee": "भोर होते ही योद्धा वापस गंगा में चले गए और ओझल हो गए, हर कोई अपने-अपने लोक को। तब व्यास ने कहा: “जो पत्नी अपने पति के साथ उसके लोक जाना चाहे, वह नदी में प्रवेश कर सकती है।” युद्ध की बहुत-सी विधवाएँ, जिनका मन अब शांत था, अपने बड़ों को प्रणाम करके गंगा में उतरीं, देह त्याग दी, और अपने पतियों के साथ चली गईं।",
 "dbab0e38": "महाभारत कहता है कि बहुत बाद में, जब राजा {janamejaya|जनमेजय} ने यह कहानी सुनी, तो वे अपने पिता {parikshit|परीक्षित} को देखने के लिए तरस गए, जिनकी साँप के काटने से मृत्यु हुई थी। वहाँ मौजूद व्यास ने यह इच्छा पूरी की: परीक्षित अपने पुत्र के सामने प्रकट हुए, और जनमेजय ने बहुत खुश होकर अपने पिता को यज्ञ के जल से स्नान कराया।",
 "7cd5f922": "कुछ साल बाद धृतराष्ट्र, गांधारी और कुंती एक साथ वन की आग में चल बसे — वे शांति से योग में बैठे थे, उसके लिए तैयार। केवल संजय बच निकले, और हिमालय चले गए।",
 "f2f2635c": "“काल ही सबकी जड़ है”",
 "d03f3b49": "युद्ध के छत्तीस साल बाद {krishna|कृष्ण} ने संसार छोड़ दिया, और उनका यादव वंश आपस में लड़कर नष्ट हो गया। {arjuna|अर्जुन} द्वारका गए और बची हुई स्त्रियों और बच्चों को इंद्रप्रस्थ की ओर ले चले। रास्ते में लाठियाँ लिए ग्वालों के एक झुंड ने उन पर हमला कर दिया, और अर्जुन ने पाया कि वे गांडीव को ठीक से उठा भी नहीं पा रहे, उन्हें अपने दिव्य अस्त्र याद नहीं आ रहे, और उनके बाण ख़त्म हो गए। बहुत-से लोगों को वे उठा ले गए। शर्म और टूटे दिल के साथ अर्जुन व्यास के आश्रम गए।",
 "afa22642": "व्यास ने सुना और कहा: “दुखी मत हो, अर्जुन। इस पूरे संसार की जड़ काल है। काल ही शक्ति देता है और काल ही उसे छीन लेता है। तुम्हारे अस्त्र एक उद्देश्य के लिए तुम्हारे पास आए थे, और वह उद्देश्य पूरा हो गया; इसलिए वे लौट गए। अब तुम्हारे और तुम्हारे भाइयों के भी जाने का समय है।” अर्जुन ने लौटकर युधिष्ठिर को बताया, और पांडव हिमालय की अपनी अंतिम यात्रा पर निकल पड़े।",
 "2ae2dc44": "व्यास ने दोनों सेनाओं के मरे हुए योद्धाओं को एक रात के लिए गंगा से बुलाया, और किसी के मन में क्रोध नहीं बचा था।",
 "90efe2ae": "{dhritarashtra|धृतराष्ट्र} ने पहली बार अपने पुत्रों को देखा, और {kunti|कुंती} ने {karna|कर्ण} को गले लगाया।",
 "4de7e108": "उन्होंने {arjuna|अर्जुन} से कहा: “काल ही शक्ति देता है और काल ही उसे छीन लेता है।”",
 "67cdd2df": "उस एक रात दुश्मन दोस्तों की तरह मिले। अगर गुस्सा ऐसे गायब हो सकता है, तो बाकी समय उसे हमारे भीतर कौन ज़िंदा रखता है?",
 "dfa78945": "पाँचवाँ वेद — और गणेश की लेखनी",
 "4ea1fb88": "पांडवों के जाने के बाद व्यास ने वह पूरी कहानी लिखी जिसे उन्होंने खुद जिया था और योग की आँख से देखा था। महाभारत कहता है कि उन्होंने तीन साल तक हर दिन सुबह जल्दी उठकर इस पर काम किया। इसमें उन्होंने केवल भरतवंशियों का युद्ध ही नहीं, बल्कि जीवन के बारे में वह सब रखा जो एक व्यक्ति को जानना चाहिए — धर्म, अर्थ, काम और मोक्ष — साथ ही सैकड़ों पुरानी कथाएँ भी: शकुंतला, नल और दमयंती, सावित्री, संक्षेप में रामकथा, और भगवद्गीता।",
 "b1cb8877": "यह ग्रंथ अपने बारे में कहता है: धर्म, अर्थ, काम और मोक्ष के बारे में जो कुछ यहाँ है, वह और कहीं भी मिल सकता है — पर जो यहाँ नहीं है, वह कहीं नहीं है। यह खुद को पाँचवाँ वेद कहता है, जिसे इसलिए रचा गया कि हर कोई, वे भी जिन्हें चारों वेद पढ़ने की अनुमति नहीं थी, उनकी सच्चाइयाँ कहानी के रूप में सुन सकें।",
 "98d3e363": "“रुकना मत” — “बिना समझे मत लिखना”",
 "3d48e24e": "यह लिखा कैसे गया? महाभारत की बहुत-सी पांडुलिपियाँ, ज़्यादातर उत्तर भारत की, पहले अध्याय में यह प्रसिद्ध कहानी बताती हैं। व्यास ने पूरा काव्य अपने मन में रच लिया था, और सोच रहे थे कि इसे संसार को कैसे दें। {brahma|ब्रह्मा} उनके सामने प्रकट हुए और बोले, “{ganesha|गणेश} का ध्यान करो। उन्हें अपना लेखक बनाओ।” व्यास ने गणेश का ध्यान किया, और गणेश आ गए।",
 "d272e01a": "गणेश राज़ी हो गए — एक शर्त पर। “लिखते समय मेरी लेखनी एक पल के लिए भी नहीं रुकनी चाहिए।” व्यास भी राज़ी हो गए — अपनी एक शर्त पर। “तो फिर आप कोई भी श्लोक तब तक नहीं लिखेंगे जब तक उसका अर्थ न समझ लें।” गणेश मुस्कुराए और बोले, “ॐ।” और उन्होंने शुरू कर दिया।",
 "31ebbeba": "जब भी व्यास को अगला भाग रचने के लिए समय चाहिए होता, वे ऐसा श्लोक बोलते जिसमें इतने छिपे अर्थ गुँथे होते कि गणेश को भी रुककर सोचना पड़ता। उस बीच व्यास कई और श्लोक रच लेते। इन कठिन श्लोकों को महाभारत की गाँठें (ग्रंथि, या व्यास-कूट) कहा जाता है।",
 "6011bdb7": "“आठ हज़ार आठ सौ श्लोक — उनका अर्थ मैं जानता हूँ, शुकदेव जानते हैं, और संजय जानते हैं या नहीं, कह नहीं सकते।” महाभारत के पहले अध्याय में व्यास इन उलझे हुए श्लोकों के बारे में ऐसा कहते हैं।",
 "bba50437": "क्या गणेश की कहानी सबसे पुराने महाभारत में है?",
 "f1d250fb": "पांडुलिपियाँ क्या कहती हैं",
 "cde51109": "जब पुणे के विद्वानों ने क्रिटिकल एडिशन के लिए पूरे भारत से महाभारत की सैकड़ों पांडुलिपियों की तुलना की, तो उन्होंने पाया कि ब्रह्मा–गणेश वाला अंश ज़्यादातर पांडुलिपियों में, ख़ासकर दक्षिण की पांडुलिपियों में, नहीं है, और उन्होंने इसे मुख्य पाठ में नहीं बल्कि टिप्पणियों में रखा। तो यह परंपरा का एक पुराना और बहुत प्यारा हिस्सा है, पर शायद काव्य के मूल भाग के बाद जोड़ा गया।",
 "830dceb6": "यह मशहूर बात कि लेखनी टूट जाने पर गणेश ने अपना एक दाँत तोड़कर कलम बना लिया, महाभारत में कहीं नहीं है; यह बाद की कथाओं से आई है और मंदिरों की कला और कथा-कहानियों में बहुत प्रिय है।",
 "e3ecb729": "व्यास के मुख से हम तक",
 "902725a6": "महाभारत कहता है कि व्यास ने इसे पहले अपने पुत्र {shuka|शुकदेव} को सिखाया, और फिर अपने शिष्यों को। यह अपना आकार भी परतों में बताता है: चौबीस हज़ार श्लोकों का एक मूल भाग, जिसे भारत कहते हैं, बिना उपकथाओं के; और एक लाख श्लोकों का पूरा महाभारत। यह कहता है कि इससे भी बड़ा एक रूप देवताओं, पितरों और गंधर्वों के बीच पढ़ा जाता है, और एक लाख श्लोक वह हैं जो मनुष्यों के लिए छोड़े गए।",
 "d5f4d7a0": "पहली बार सबके सामने यह कथा अर्जुन के परपोते राजा {janamejaya|जनमेजय} के महान सर्प-यज्ञ में सुनाई गई। व्यास वहाँ मौजूद थे, और राजा के कहने पर उन्होंने अपने शिष्य {vaishampayana|वैशंपायन} से कहा, “मुझसे जो कुछ सुना है, वह सब इन्हें सुनाओ।” बरसों बाद, वैशंपायन से कथा सुन चुके सूत {ugrashravas|उग्रश्रवा} नैमिषारण्य आए और {shaunaka|शौनक} और वहाँ के ऋषियों को सब कुछ फिर से सुनाया। यही वह कथा है जो हमारे पास है: कहानी के भीतर कहानी, उसके भीतर फिर कहानी।",
 "f2f4bed4": "महाभारत तेलुगु में आंध्र महाभारतमु के रूप में आया, जिसे कवित्रयम् कहलाने वाले तीन कवियों ने रचा। नन्नय ने ग्यारहवीं सदी में राजमहेंद्रवरम में राजा राजराजनरेंद्र के दरबार में इसे शुरू किया; तेरहवीं सदी में तिक्कन ने इसका ज़्यादातर भाग पूरा किया; और अरण्य पर्व का जो हिस्सा नन्नय अधूरा छोड़ गए थे, उसे एर्रन ने पूरा किया। अक्सर कहा जाता है कि लिखित कला के रूप में तेलुगु कविता नन्नय के भारत से ही शुरू होती है।",
 "6ee1209e": "महाभारत, आदि पर्व, अध्याय 1 — व्यास का तीन साल का काम, भारत और महाभारत के आकार, और 8,800 उलझे हुए श्लोक; ब्रह्मा–गणेश वाला अंश प्रचलित (उत्तरी) पांडुलिपियों में मिलता है और क्रिटिकल एडिशन में टिप्पणियों में रखा गया है। जनमेजय का सर्प-यज्ञ और वैशंपायन का कथा-पाठ: आदि पर्व (आस्तीक खंड और आगे)। “जो यहाँ नहीं, वह कहीं नहीं”: आदि पर्व और स्वर्गारोहण पर्व। टूटे दाँत की बात बाद की कथा है।",
 "eea20742": "महाभारत खुद को पाँचवाँ वेद कहता है: जो इसमें नहीं है, वह कहीं नहीं है।",
 "f1074691": "बहुत-सी पांडुलिपियों में {ganesha|गणेश} बिना रुके लिखते हैं, और व्यास उनसे हर श्लोक पहले समझवाते हैं।",
 "bbcfd824": "यह कथा पहले {vaishampayana|वैशंपायन} ने {janamejaya|जनमेजय} के यज्ञ में सुनाई, फिर {ugrashravas|उग्रश्रवा} ने नैमिषारण्य में।",
 "8b1527cb": "व्यास की शर्त थी: “जो समझा न हो, वह मत लिखना।” अगर हम केवल वही कहें या लिखें जो हमने सच में समझा हो, तो क्या बदल जाएगा?",
 "f08639bb": "शुकदेव, अग्नि से जन्मे पुत्र",
 "ed45456e": "अपनी माँ के वंश के लिए व्यास के तीन पुत्र हुए थे, पर वे अपना एक पुत्र चाहते थे — धरती जैसा स्थिर, जल जैसा पवित्र, हवा जैसा स्वतंत्र, अग्नि जैसा तेजस्वी और आकाश जैसा विशाल। वे मेरु पर्वत पर सुनहरे कर्णिकार वृक्षों के एक वन में गए और सौ साल तक {shiva|शिव} की कठोर तपस्या की। प्रसन्न होकर शिव ने उन्हें ठीक वैसा ही पुत्र वरदान में दिया।",
 "89fc02be": "कुछ समय बाद व्यास पवित्र अग्नि जलाने के लिए दो अरणी लकड़ियों को रगड़ रहे थे, तभी {ghritachi|घृताची} नाम की अप्सरा एक सुंदर मादा तोते (शुकी) के रूप में वहाँ से गुज़री। उसे देखकर व्यास के मन में कामना जागी; उन्होंने मन को रोकने की कोशिश की, फिर भी उनका वीर्य अरणी की लकड़ियों पर गिर पड़ा। वे लकड़ियाँ रगड़ते रहे — और जैसे अग्नि पैदा होती है, वैसे ही उन लकड़ियों से एक तेजस्वी बालक पैदा हुआ। तोते के कारण उसका नाम {shuka|शुक} रखा गया।",
 "e901c6db": "बालक को नहलाने के लिए गंगा जी स्वयं आईं; उसके लिए आकाश से एक दंड और काला मृगचर्म गिरा; देवताओं ने बाजे बजाए और अप्सराओं ने नृत्य किया। शुक ने देवताओं के गुरु {brihaspati|बृहस्पति} से और फिर अपने पिता से पूरा वेद सीखा — और जन्म से ही उन्हें संसार की किसी चीज़ से मोह नहीं था।",
 "759d68b7": "जनक के द्वार पर परीक्षा",
 "b3d7f7f3": "शिक्षा पूरी करने के लिए व्यास ने शुक को मिथिला के राजा {janaka|जनक} के पास भेजा — वे ऐसे राजा थे जो राज करते हुए भी मुक्त थे। शुक पैदल वहाँ गए। महल के द्वार पर पहरेदारों ने उन्हें रोक दिया और कोई स्वागत नहीं किया; वे बिना क्रोध या दुख के तीन दिन तक धूप में शांति से खड़े रहे। फिर उन्हें एक सुंदर बगीचे में ले जाया गया, जहाँ सुंदर युवतियों ने हर तरह के सुख देकर उनकी सेवा की। सम्मान हो या अनादर, वे किसी से विचलित नहीं हुए — पहले की तरह ही खाते, सोते और ध्यान करते रहे।",
 "cf7c3e0b": "जनक आए, उनका सम्मान किया और उन्हें मुक्ति का मार्ग सिखाया। अंत में उन्होंने कहा: “जो कुछ मैं सिखा सकता था, वह तुम पहले से जानते हो। तुम्हें किसी चीज़ की कमी नहीं — बस अपने ज्ञान पर विश्वास की कमी है।” शुक अपने पिता के पास लौट आए। भागवत यह कथा दूसरे ढंग से कहता है और शुक को अवधूत बताता है — एक घूमते हुए मुनि, जो बिना वस्त्रों के, बच्चे की तरह या संसार से बेसुध व्यक्ति की तरह घूमते थे, हमेशा आत्मा में डूबे हुए।",
 "f5637c90": "एक दिन शुक ने संसार को पूरी तरह छोड़ देने का निश्चय किया। वे योग-बल से पर्वत की चोटी से आकाश में उठे, इतने तेजस्वी होकर कि उन्हें रास्ता देने के लिए शिखर फट गए, और वे उससे भी आगे चले गए। व्यास, जो अपने पुत्र को सबसे ज़्यादा प्यार करते थे, “शुक! मेरे बेटे!” पुकारते हुए उनके पीछे दौड़े। और हर ओर से — पहाड़ों से, जंगलों से, नदियों से — उत्तर गूँज उठा। क्योंकि शुक सबके साथ एक हो गए थे, और सब कुछ उनकी ओर से उत्तर दे रहा था।",
 "2c2aded8": "रास्ते में व्यास एक नदी के पास से गुज़रे जहाँ अप्सराएँ स्नान कर रही थीं। जब युवा शुक उड़कर पास से गए थे, तब उन्होंने अपने को ढकने की परवाह नहीं की थी; पर जब बूढ़े पिता आए, तो उन्होंने जल्दी से कपड़े पहन लिए। हैरान होकर व्यास ने कारण पूछा। वे बोलीं, “आपका पुत्र स्त्री और पुरुष का भेद नहीं देखता। उसका मन निर्मल है। आपका मन अभी भी यह भेद देखता है।” दुखी पिता को सांत्वना देने शिव आए: “आपके पुत्र ने सबसे ऊँचा लक्ष्य पा लिया है। और उसकी छाया सदा आपके साथ रहेगी।” महाभारत स्नान करती अप्सराओं और छाया, दोनों की बात कहता है; भागवत भी अप्सराओं की कथा याद रखता है।",
 "431bc302": "“जब वह संसार त्यागकर जा रहा था — अभी जनेऊ भी नहीं हुआ था, कोई कर्तव्य बाकी नहीं था — तब बिछड़ने के दुख से व्याकुल द्वैपायन ने ‘बेटा!’ कहकर पुकारा। और उसके साथ एक हो चुके पेड़ों ने उत्तर दिया। सब प्राणियों के हृदय उस मुनि को मैं प्रणाम करता हूँ।” (भागवत 1.2.2)",
 "a640532b": "क्या शुक ने विवाह किया?",
 "a231fcb3": "जहाँ ग्रंथों में अंतर है",
 "f2307136": "महाभारत और भागवत में शुक जन्म से ही संन्यासी हैं और कभी विवाह नहीं करते। देवी भागवत पुराण इसे अलग तरह से कहता है: वहाँ शुक जनक से सीखने के बाद घर लौटते हैं, पीवरी नाम की स्त्री से विवाह करते हैं और उनके बच्चे होते हैं, फिर अंत में मुक्ति पाते हैं। दोनों कथाएँ इस बात पर सहमत हैं कि अंत में वे परमात्मा के साथ एक हो गए।",
 "fe7c08fd": "इसीलिए तोता शुक की पहचान बन गया। मूर्तियों और चित्रों में उन्हें अक्सर तोते के मुख के साथ या पास बैठे तोते के साथ दिखाया जाता है। तेलुगु में तोते को आज भी शुकम् भी कहा जाता है।",
 "602b3f59": "महाभारत, शांति पर्व (मोक्षधर्म खंड, शुक की कथा) — मेरु पर व्यास का तप, अरणी से शुक का जन्म, जनक की शिक्षा, शुक का प्रस्थान, स्नान करती अप्सराएँ और शिव की सांत्वना। भागवत पुराण, स्कंध 1, अध्याय 2 और 4 (पेड़ों की गूँज; अप्सराएँ)। देवी भागवत पुराण, स्कंध 1 (शुक का विवाह)।",
 "a167197b": "{ghritachi|घृताची} को तोते के रूप में देखने के बाद अरणी की लकड़ियों से {shuka|शुक} का जन्म हुआ।",
 "825daab0": "{janaka|जनक} ने अनादर और सुख, दोनों से उनकी परीक्षा ली; वे किसी से भी विचलित नहीं हुए।",
 "59eb499c": "जब व्यास ने “बेटा!” पुकारा, तो सारे संसार ने उत्तर दिया — क्योंकि शुक सबके साथ एक हो गए थे।",
 "be4537e4": "महान व्यास भी अपने पुत्र के जाने पर रो पड़े। जिसे हम प्यार करते हैं, उसके लिए दुखी होना — यह जानते हुए भी कि वह सुखी है — क्या कमज़ोरी है?",
 "7330c78b": "भागवत, पुराण — और काशी में भूख",
 "0f77fa17": "भागवत एक अचरज से शुरू होता है: वेद का विभाजन करने वाले और महाभारत रचने वाले व्यास सरस्वती के किनारे उदास और खाली मन से बैठे हैं। {narada|नारद} आए और उन्हें कारण बताया — उन्होंने धर्म और कर्तव्य की बात तो कही थी, पर भगवान की महिमा को केवल उसी के लिए नहीं गाया था। फिर नारद ने उन्हें अपने पिछले जन्म की कथा सुनाई, जब वे एक दासी के पुत्र थे।",
 "8597e3bf": "नारद के जीवन में पूरी कथा पढ़ो: दासी का पुत्र",
 "2ee2d7bf": "नारद के जाने के बाद व्यास नदी के किनारे शम्याप्रास नाम के अपने आश्रम में ध्यान में बैठे, और अपने निर्मल मन में उन्होंने भगवान के दर्शन किए। फिर उन्होंने श्रीमद्भागवत की रचना की — भगवान के अवतारों की कथा, और सबसे बढ़कर श्रीकृष्ण की कथा — और उसे अपने पुत्र {shuka|शुक} को सिखाया। भागवत में ही मुनि पूछते हैं, “जिन शुक को किसी चीज़ की चाह नहीं थी, उन्होंने एक ग्रंथ क्यों सीखा?” उत्तर है: जो मुनि केवल आत्मा में ही आनंद पाते हैं, वे भी बिना किसी कारण हरि से उनके गुणों के लिए प्रेम करते हैं। भगवान की मधुरता ऐसी ही है।",
 "cc74efb9": "गंगा के किनारे सात दिन",
 "9cde6d74": "अर्जुन के पोते राजा {parikshit|परीक्षित} ने एक बार गुस्से में आकर ध्यान में बैठे एक मुनि के गले में मरा हुआ साँप डाल दिया। मुनि के छोटे बेटे ने उन्हें श्राप दिया: सात दिन में नाग तक्षक उन्हें डसेगा और वे मर जाएँगे। परीक्षित ने श्राप का विरोध नहीं किया। उन्होंने अपना राज्य बेटे को सौंप दिया, गंगा के किनारे गए और मृत्यु तक उपवास करने बैठ गए। बड़े-बड़े ऋषि उनके चारों ओर इकट्ठा हो गए।",
 "04b83714": "तभी युवा शुक घूमते हुए वहाँ आ पहुँचे — सोलह बरस के, बिना वस्त्रों के, और उनके पीछे चिढ़ाते हुए बच्चे, जो उन्हें पागल समझ रहे थे। सारे ऋषि, सबसे बूढ़े भी, उनके सम्मान में खड़े हो गए। परीक्षित ने उनसे पूछा: “जो मनुष्य मरने वाला हो, उसे क्या करना चाहिए?” और सात दिन तक, बिना रुके, शुक ने उन्हें पूरा भागवत सुनाया। सातवें दिन के अंत तक परीक्षित का मन भगवान में स्थिर हो गया था, और जब तक्षक आया, तब तक वे मुक्त हो चुके थे।",
 "680d8b5f": "इसीलिए आज भी तेलुगु प्रदेशों में मंदिरों और घरों में भागवत का सात दिन तक पाठ (भागवत सप्ताह) होता है। पंद्रहवीं शताब्दी में बम्मेर पोतन का रचा आंध्र महाभागवतम् इतना प्रिय है कि उसके कई पद्य तेलुगु परिवारों को कंठस्थ हैं।",
 "b8a0ad68": "अठारह पुराण",
 "504a67a7": "परंपरा केवल भागवत ही नहीं, अठारहों महापुराण व्यास के ही मानती है — विष्णु, शिव, स्कंद, मार्कंडेय, पद्म, गरुड़ और बाकी। कहते हैं कि उन्होंने सृष्टि, राजवंशों, अवतारों और तीर्थों की पुरानी कथाओं को इन ग्रंथों में सजाया और सूत {romaharshana|रोमहर्षण} को दिया, जिनके पुत्र उग्रश्रवा ने उन्हें नैमिषारण्य के ऋषियों को सुनाया। कई पुराण उसी दृश्य से शुरू होते हैं।",
 "6fec88d6": "आज के विद्वान मानते हैं कि पुराण कई शताब्दियों में धीरे-धीरे बढ़े और बहुत से लोगों ने उनमें जोड़ा। परंपरा का उत्तर है कि पुराण भी वेद की तरह गढ़े नहीं गए, सजाए गए — और हर युग में उस सजाने का नाम ही “व्यास” है।",
 "1a0c6d13": "काशी में भूख",
 "b9fbbec9": "स्कंद पुराण का काशी खंड एक कथा सुनाता है जो दिखाती है कि व्यास को भी गुस्सा आ सकता था। वे हज़ारों शिष्यों के साथ काशी आए। उनकी परीक्षा लेने के लिए {shiva|शिव} ने ऐसा किया कि कई दिनों तक नगर के किसी भी घर ने उन्हें भिक्षा नहीं दी। भूखे और क्रोधित व्यास ने नगर को श्राप देने के लिए हाथ उठाया: “काशी में न विद्या रहे, न धन, न मुक्ति!”",
 "e67ef121": "श्राप पड़ने से पहले ही एक घर के द्वार पर एक दयालु गृहिणी प्रकट हुईं और उन्हें और उनके सभी शिष्यों को भोजन के लिए बुलाया। वे स्वयं पार्वती थीं — {annapurna|अन्नपूर्णा} के रूप में, और उनके पास पति के रूप में शिव खड़े थे। जब सबने भोजन कर लिया, तो शिव ने कड़ाई से कहा: “बस एक दिन की भूख पर तुम मुक्ति की नगरी को श्राप देने को तैयार हो गए। तुम काशी में नहीं रह सकते।” व्यास ने क्षमा माँगी, और उन्हें गंगा के उस पार रहने और कुछ खास दिनों में नगर में आने की अनुमति मिली। काशी के सामने नदी के उस पार का व्यास मंदिर आज भी इस कथा से जुड़ा है।",
 "8fe81f2f": "भागवत पुराण, स्कंध 1, अध्याय 4–7 (व्यास की उदासी, नारद, भागवत की रचना और शुक को उसकी शिक्षा); अध्याय 18–19 (परीक्षित का श्राप और शुक का आगमन); स्कंध 12 (परीक्षित का अंत)। पुराणों के अपने आरंभ में व्यास और रोमहर्षण के नाम आते हैं। स्कंद पुराण, काशी खंड (व्यास का श्राप और अन्नपूर्णा का भोजन; गंगा के उस पार उनका निवास)।",
 "8349831b": "{narada|नारद} के आने के बाद व्यास ने भागवत रचा और {shuka|शुक} को सिखाया।",
 "cb72acb7": "शुक ने मृत्यु के निकट {parikshit|परीक्षित} को सात दिन में यह सुनाया — इसीलिए भागवत सप्ताह होता है।",
 "0e9fcbaa": "काशी में भूखे व्यास नगर को श्राप देने ही वाले थे, तब {annapurna|अन्नपूर्णा} ने उन्हें भोजन कराया।",
 "66482e10": "व्यास भी भूख के कारण पूरे नगर को श्राप देने वाले थे। जब तुम भूखे या थके होते हो, तब अपने गुस्से के बारे में तुम क्या देखते हो?",
 "417708ed": "बादरायण — ब्रह्मसूत्र",
 "961fe277": "उपनिषदों में ब्रह्म के बारे में — जो सबके पीछे की एक ही सच्चाई है — सबसे गहरी शिक्षाएँ भरी हैं; पर वे कई आवाज़ों में, कथाओं, पहेलियों और संवादों में बोलते हैं, और कभी-कभी अलग-अलग बातें कहते लगते हैं। किसी को उनके अर्थ को एक साफ़, छोटे रूप में इकट्ठा करना था, जिसे विद्यार्थी कंठस्थ कर सके और उस पर विचार कर सके। वह ग्रंथ है ब्रह्मसूत्र, जिसे वेदांत सूत्र भी कहते हैं, और उसके रचयिता का नाम है बादरायण।",
 "ef6734ae": "बादरायण का अर्थ है “बदरी वन वाले”, और परंपरा हमेशा से उन्हें स्वयं व्यास ही मानती आई है, जिन्होंने बदरी के बेर के पेड़ों के बीच तप किया था। मध्वाचार्य और कई दूसरे आचार्य इस बात को दृढ़ता से मानते हैं। कुछ बाद के विद्वान, और कई आधुनिक विद्वान, सोचते हैं कि बादरायण शायद कोई दूसरे, बाद के आचार्य रहे होंगे। फिर भी परंपरा इन दोनों नामों को एक ही मानती है।",
 "cf155f9a": "“अब, इसलिए, ब्रह्म की जिज्ञासा”",
 "ba5740aa": "ब्रह्मसूत्र लगभग साढ़े पाँच सौ बहुत छोटे वाक्य हैं — कभी-कभी सिर्फ़ दो-तीन शब्दों के — जो चार अध्यायों में हैं: उपनिषद ब्रह्म के बारे में क्या सिखाते हैं; वह शिक्षा दूसरे मतों को कैसे उत्तर देती है; साधना का मार्ग; और उसका फल, मुक्ति। वे इस तरह शुरू होते हैं:",
 "d3a78024": "“अब, इसलिए, ब्रह्म की जिज्ञासा।” “जिससे इस जगत का जन्म आदि (जन्म, पालन और लय) होता है, वही ब्रह्म है।” — पहले दो सूत्र।",
 "167de2c6": "सूत्र इतने संक्षिप्त हैं कि उन्हें अकेले पढ़कर समझा नहीं जा सकता; हर सूत्र को कोई गुरु खोलकर समझाए, यह ज़रूरी है। इसीलिए महान आचार्यों ने उन पर भाष्य लिखे — अद्वैत के लिए {shankara|शंकराचार्य}, विशिष्टाद्वैत के लिए रामानुजाचार्य (श्रीभाष्य), द्वैत के लिए मध्वाचार्य, और उनके बाद और भी कई। हर एक ने बादरायण के सूत्रों में अपना वेदांत दर्शन पाया।",
 "fefa3120": "तीन नींव — सब व्यास से जुड़ी",
 "1b9ef60d": "वेदांत तीन नींवों पर टिका है — प्रस्थानत्रयी: उपनिषद, भगवद्गीता और ब्रह्मसूत्र। उपनिषद व्यास के सजाए वेदों के अंत में आते हैं; गीता व्यास के रचे महाभारत में है, जिसे {krishna|श्रीकृष्ण} ने कहा; और ब्रह्मसूत्र बादरायण के हैं। यानी तीनों उन्हीं के हाथों से हम तक पहुँचे। सूत्रों में बादरायण दूसरे आचार्यों के नाम भी लेते हैं — परंपरा के अनुसार उनके अपने शिष्य और मीमांसा सूत्रों के रचयिता {jaimini|जैमिनि} भी इनमें हैं — कभी उनसे सहमत होते हुए, कभी असहमत।",
 "cde4ada5": "परंपरा पतंजलि के योगसूत्रों पर सबसे पुराने भाष्य, जिसे व्यास भाष्य कहते हैं, का रचयिता भी व्यास को ही मानती है। वे व्यास और द्वीप वाले मुनि एक ही हैं या नहीं, इस पर भी विद्वानों में बहस है; परंपरा उन्हें बस व्यास कहती है और योग का अर्थ सिखाने वाले पहले गुरु के रूप में उनका सम्मान करती है।",
 "ca1586ee": "गंगा किनारे के बूढ़े बाबा",
 "030ecb72": "बहुत बाद की एक कथा, जो शंकर की जीवनियों (शंकर दिग्विजय ग्रंथों) में आती है, कहती है कि जब सोलह बरस के युवा शंकर ने ब्रह्मसूत्रों पर अपना भाष्य पूरा किया, तब गंगा के किनारे एक बूढ़े ब्राह्मण उनके पास आए और एक सूत्र के उनके अर्थ को चुनौती दी। कई दिन तक दोनों में शास्त्रार्थ चला। आख़िर में शंकर के शिष्य पद्मपाद ने पहचाना कि वे बूढ़े बाबा कौन थे: स्वयं व्यास।",
 "246c5948": "शंकर ने उन्हें प्रणाम किया। व्यास भाष्य से प्रसन्न हुए, और शंकर को, जिनका जीवन सोलह वर्ष में ही समाप्त होना था, सोलह वर्ष और का आशीर्वाद दिया, ताकि वे पूरे भारत में यह शिक्षा फैला सकें। यह कथा किसी प्राचीन ग्रंथ में नहीं है; यह बाद की एक प्यारी परंपरा है — पर यह दिखाती है कि हर युग के गुरुओं ने व्यास को अपने पीछे खड़ा महसूस किया है।",
 "8cdc0009": "बादरायण के ब्रह्मसूत्र (वेदांत सूत्र), अध्याय 1, पाद 1, सूत्र 1–2; शंकर, रामानुज और मध्व के भाष्य। योगसूत्रों पर व्यास भाष्य। शंकर और व्यास के मिलन की कथा बाद की शंकर दिग्विजय जीवनियों में है, प्राचीन ग्रंथों में नहीं।",
 "9fe694b9": "परंपरा व्यास को ही ब्रह्मसूत्रों के रचयिता बादरायण मानती है; कुछ विद्वान सोचते हैं कि वे अलग-अलग व्यक्ति थे।",
 "9a977070": "सूत्र “अथातो ब्रह्मजिज्ञासा” से शुरू होते हैं।",
 "d8130218": "उपनिषद, गीता और ब्रह्मसूत्र — प्रस्थानत्रयी — तीनों व्यास के द्वारा ही आए; {shankara|शंकराचार्य} और दूसरे आचार्यों ने उन पर भाष्य लिखे।",
 "3a2f8aae": "ब्रह्मसूत्र इतने छोटे हैं कि उन्हें समझाने के लिए गुरु चाहिए। तुम्हें क्या लगता है, कुछ ज्ञान सिर्फ़ किताबों से नहीं, बल्कि एक व्यक्ति से दूसरे व्यक्ति तक सबसे अच्छी तरह क्यों पहुँचता है?",
 "a62e3a91": "गुरु पूर्णिमा — “मुनियों में मैं व्यास हूँ”",
 "75567ec3": "भगवद्गीता के दसवें अध्याय में {krishna|श्रीकृष्ण} {arjuna|अर्जुन} को बताते हैं कि संसार में उनकी महिमा सबसे ज़्यादा कहाँ चमकती है। जिन बहुत सी चीज़ों के वे नाम लेते हैं, उनमें व्यास का नाम भी है — उसी कवि का, जो यह गीता सुना रहे थे।",
 "5490b686": "“वृष्णियों में मैं वासुदेव हूँ; पांडवों में धनंजय (अर्जुन); मुनियों में मैं व्यास हूँ; कवियों में कवि उशना (शुक्राचार्य)।” (भगवद्गीता 10.37)",
 "12f639c7": "अगर तुम विष्णु सहस्रनाम सीख रहे हो, तो हर बार शुरू करते समय तुम व्यास को प्रणाम करते ही हो। आरंभ के प्रार्थना-श्लोकों में से दो उन्हीं के लिए हैं — वसिष्ठ से शुक तक उनके पूरे वंश का नाम लेते हुए, और उन्हें विष्णु से एक बताते हुए:",
 "2ab7b26a": "“वसिष्ठ के परपोते, शक्ति के पोते, पराशर के पुत्र, शुक के पिता, निष्कलंक, तप के भंडार व्यास को मैं प्रणाम करता हूँ। विष्णु-रूप व्यास को, और व्यास-रूप विष्णु को; वेदों के भंडार, वसिष्ठ के वंशज को बार-बार नमस्कार।”",
 "641852b3": "व्यास पूर्णिमा",
 "4d435ae3": "आषाढ़ महीने की पूर्णिमा गुरु पूर्णिमा है — इसे व्यास पूर्णिमा भी कहते हैं। परंपरा कहती है कि उसी दिन व्यास का जन्म हुआ था। उस दिन विद्यार्थी अपने गुरुओं का सम्मान करते हैं; तेलुगु घरों में और संगीत, नृत्य और वेद की पाठशालाओं में बच्चे गुरु के चरणों में प्रणाम करते हैं। उस दिन संन्यासी व्यास पूजा करते हैं और चातुर्मास्य शुरू करते हैं — बरसात के चार महीने एक ही जगह रहकर अध्ययन और शिक्षा देना।",
 "5656dbab": "इतने सारे गुरुओं में व्यास ही क्यों? क्योंकि एक हिंदू बच्चा जो कुछ सीखता है, लगभग सब — वेद, महाभारत, गीता, भागवत, पुराण, वेदांत — उन्हीं के द्वारा आया है। एक पुरानी कहावत है: “व्यासोच्छिष्टं जगत्सर्वम्” — “सारा संसार व्यास का छोड़ा हुआ ही है”; जो कुछ कहने लायक है, वह सब वे पहले ही कह चुके हैं।",
 "2da65757": "तेलंगाना में गोदावरी के किनारे बासर में ज्ञान सरस्वती का प्रसिद्ध मंदिर है; बहुत से तेलुगु परिवार छोटे बच्चों का अक्षराभ्यास, यानी पहली बार अक्षर लिखवाने का संस्कार, कराने वहाँ जाते हैं। मंदिर की परंपरा कहती है कि कुरुक्षेत्र युद्ध के बाद तप के लिए शांत जगह ढूँढ़ते हुए व्यास यहाँ आए और मुट्ठी भर-भर रेत से देवी की मूर्ति बनाई; कहते हैं कि इस जगह को कभी व्यासपुरी कहा जाता था, और “बासर” नाम उसी से निकला है।",
 "0c7b3e16": "आज भी जीवित",
 "cbd30345": "व्यास की मृत्यु की कथा कहीं नहीं मिलती। परंपरा उन्हें सात चिरंजीवियों में गिनती है — वे दीर्घजीवी, जो इस युग भर धरती पर रहते हैं। एक प्रसिद्ध श्लोक उनके नाम गिनाता है:",
 "691b1189": "“अश्वत्थामा, बलि, व्यास, हनुमान, विभीषण, कृप और परशुराम — ये सातों चिरंजीवी हैं।”",
 "de136b34": "देखो, उस सूची में उनके साथ कौन-कौन है: {ashvatthama|अश्वत्थामा}, जिसे उन्होंने एक बार अपना अस्त्र वापस न ले पाते हुए अपनी आँखों से देखा था; रामकथा के {hanuman|हनुमान} और {vibhishana|विभीषण}; भृगु वंश के {parashurama|परशुराम}। परंपरा कहती है कि वीरों के युग को लिखने वाले वे मुनि आज भी कहीं हमारे बीच घूम रहे हैं — शायद हिमालय में, बदरी में, जहाँ से उनकी कथा शुरू हुई थी।",
 "db375f2a": "“भुजाएँ उठाकर मैं पुकारता हूँ”",
 "e743178e": "महाभारत के बिल्कुल अंत में, युद्ध, हानि और ज्ञान से भरे अठारह पर्वों के बाद, व्यास अपनी आवाज़ में कुछ श्लोक कहते हैं, जिन्हें भारत सावित्री कहते हैं। उन्होंने सब कुछ देखा है — राजा और उनका घमंड, परिवार और उनके झगड़े, देवता और मृतक। और हमसे उनकी आख़िरी पुकार बहुत सरल है:",
 "3d72ff6a": "“भुजाएँ ऊपर उठाकर मैं पुकार रहा हूँ — पर कोई मेरी बात नहीं सुनता: धर्म से ही धन भी मिलता है और सुख भी। तो फिर धर्म का पालन क्यों नहीं किया जाता?”",
 "7f13bc22": "यही हैं व्यास: द्वीप के साँवले बालक, वेदों को सजाने वाले, वे दादा जिन्होंने अपने ही परिवार को अपना नाश करते देखा और फिर भी वह कथा सुनाई, ताकि हम उससे सीख सकें। जब भी हम गीता खोलते हैं, सहस्रनाम का पाठ करते हैं या पांडवों की कोई कथा सुनते हैं, हम उन्हीं के चरणों में बैठे होते हैं।",
 "4b928cbe": "गीता में नारद: “देवर्षियों में मैं नारद हूँ”",
 "60cff1e0": "भगवद्गीता 10.37 (महाभारत, भीष्म पर्व)। विष्णु सहस्रनाम स्तोत्र के पाठ के आरंभ में व्यास की प्रार्थना के श्लोक। महाभारत, स्वर्गारोहण पर्व, अंतिम अध्याय (भारत सावित्री के श्लोक)। गुरु पूर्णिमा, व्यास पूजा और चातुर्मास्य: जीवित परंपरा। चिरंजीवियों वाला श्लोक प्रार्थना में बोला जाने वाला एक पारंपरिक श्लोक है। बासर और व्यासपुरी: मंदिर की परंपरा।",
 "faae9ed7": "गीता में कृष्ण कहते हैं: “मुनियों में मैं व्यास हूँ।”",
 "71c76a8f": "आषाढ़ पूर्णिमा गुरु पूर्णिमा है — व्यास पूर्णिमा — जिस दिन हम अपने गुरुओं का सम्मान करते हैं।",
 "3c154d32": "वे सात चिरंजीवियों में से एक हैं, और उनकी आख़िरी पुकार है: “धर्म से धन और सुख मिलते हैं — फिर उसका पालन क्यों नहीं होता?”",
 "6d603aa6": "व्यास कहते हैं कि वे भुजाएँ उठाकर पुकारते हैं और कोई नहीं सुनता। तुम्हें क्या लगता है, लोग यह मानते हुए भी कि धर्म से भला होता है, उसका पालन करना कठिन क्यों पाते हैं?",
 "6d4240dd": "सत्यवती (व्यास की माता)",
 "b2310e5f": "मछुआरों के मुखिया की बेटी, जो यात्रियों को नाव से यमुना पार कराती थीं। पराशर से व्यास की माता बनीं, और बाद में कुरु राजा शांतनु की रानी।",
 "3a648b5b": "उपरिचर वसु",
 "9d6a4e3f": "चेदि के राजा, जो इंद्र को इतने प्रिय थे कि उन्हें आकाश में चलने वाला स्फटिक का रथ मिला था। सत्यवती के जन्मदाता पिता।",
 "adc64407": "अद्रिका",
 "813f2811": "एक अप्सरा, जो श्राप के कारण यमुना में मछली बनकर रहीं और जिन्होंने सत्यवती और उनके जुड़वाँ भाई को जन्म दिया।",
 "5c2f7108": "मछुआरों के मुखिया (दाशराज)",
 "fe3286df": "यमुना के मछुआरों के मुखिया, जिन्होंने सत्यवती को अपनी बेटी की तरह पाला।",
 "d2225a98": "पैल",
 "bf4e505b": "व्यास के शिष्य, जिन्हें ऋग्वेद मिला।",
 "e98cb768": "वैशंपायन",
 "e6105180": "व्यास के शिष्य, जिन्हें यजुर्वेद मिला, और जिन्होंने राजा जनमेजय के यज्ञ में पहली बार सबके सामने महाभारत सुनाया।",
 "dd4d2457": "जैमिनि",
 "bc5b19cd": "व्यास के शिष्य, जिन्हें सामवेद मिला; परंपरा उन्हें मीमांसा सूत्रों का रचयिता भी मानती है।",
 "56899cbb": "सुमंतु",
 "46d44f74": "व्यास के शिष्य, जिन्हें अथर्ववेद मिला।",
 "faa7d05d": "रोमहर्षण (लोमहर्षण)",
 "01dd65c4": "वे सूत (कथावाचक), जिन्हें व्यास ने इतिहास और पुराण दिए। उनकी कथाएँ सुनकर सुनने वालों के रोंगटे खड़े हो जाते थे — इसीलिए उनका यह नाम पड़ा।",
 "9625f889": "उग्रश्रवा (सौति)",
 "feef15cb": "रोमहर्षण के पुत्र, जिन्होंने नैमिषारण्य में शौनक और ऋषियों को पूरा महाभारत सुनाया।",
 "22f0a2a2": "शांतनु",
 "32fe7236": "हस्तिनापुर के कुरु राजा, पहले गंगा के और फिर सत्यवती के पति; भीष्म के पिता।",
 "88ef685f": "विचित्रवीर्य",
 "68314d30": "शांतनु और सत्यवती के छोटे पुत्र, जिनकी कम उम्र में ही बिना संतान के मृत्यु हो गई।",
 "dd2c37b2": "अंबिका",
 "cd7f0176": "काशी की राजकुमारी, विचित्रवीर्य की बड़ी विधवा पत्नी और धृतराष्ट्र की माता।",
 "5fd9f5da": "अंबालिका",
 "098e318e": "काशी की राजकुमारी, विचित्रवीर्य की छोटी विधवा पत्नी और पांडु की माता।",
 "e6b60b4e": "पांडु",
 "ceff14ac": "व्यास और अंबालिका के पुत्र, जन्म से ही पीले रंग के; एक महान विजेता और पांडवों के पिता।",
 "be41e385": "विदुर",
 "8f348b3b": "व्यास और महल की एक दासी के पुत्र, कुरुओं के सबसे बुद्धिमान सलाहकार — मनुष्य रूप में जन्मे स्वयं धर्म।",
 "3a697a8b": "अणी-मांडव्य",
 "61abcbc2": "एक मौन मुनि, जिन्हें गलती से चोर समझकर दंड दिया गया, और जिन्होंने धर्म को मनुष्य बनकर जन्म लेने का श्राप दिया — विदुर के रूप में।",
 "b63ffa4f": "दुर्योधन",
 "961180c9": "धृतराष्ट्र के सौ पुत्रों में सबसे बड़ा, पांडवों का बड़ा प्रतिद्वंद्वी।",
 "56ac3c6d": "दुःशला",
 "51fda7d4": "धृतराष्ट्र और गांधारी की इकलौती बेटी, सौ कौरवों की बहन।",
 "4e16a864": "द्रुपद",
 "48b658fd": "पांचाल के राजा और द्रौपदी के पिता।",
 "3607ac0b": "संजय",
 "fbc26a46": "धृतराष्ट्र के सारथी और साथी, जिन्हें व्यास ने दिव्य दृष्टि दी ताकि वे पूरा युद्ध देखकर सुना सकें — भगवद्गीता समेत।",
 "cd2032e6": "अश्वत्थामा",
 "862ad19b": "उत्तरा",
 "646aa0cb": "विराट की राजकुमारी, अभिमन्यु की पत्नी और परीक्षित की माता।",
 "5e099879": "परीक्षित",
 "17c176c1": "अर्जुन के पोते, जिन्हें गर्भ में ही श्रीकृष्ण ने बचाया। सात दिन में मृत्यु का श्राप मिलने पर उन्होंने शुक से भागवत सुना।",
 "87b35f3c": "जनमेजय",
 "e6480600": "परीक्षित के पुत्र, जिनके महान सर्प-यज्ञ में पहली बार महाभारत सुनाया गया।",
 "0bc0e82c": "गणेश",
 "264e80eb": "शिव और पार्वती के हाथी के मुख वाले पुत्र, विघ्नों को दूर करने वाले और विद्या के स्वामी।",
 "4dedda48": "शुक",
 "59fb9e25": "घृताची",
 "1face50e": "इंद्र के स्वर्ग की एक अप्सरा।",
 "a555f4c7": "अन्नपूर्णा",
 "e728542c": "संसार को अन्न देने वाली देवी के रूप में पार्वती, जिनकी काशी में पूजा होती है।",
 "6b147c0d": "आदि शंकराचार्य",
 "05d08965": "अद्वैत वेदांत के महान आचार्य, जिन्होंने उपनिषदों, गीता और ब्रह्मसूत्रों पर भाष्य लिखे।",
 "2abe069f": "व्यास",
 "442f7aae": "कृष्ण द्वैपायन, पराशर और सत्यवती के पुत्र, जिन्होंने वेद का विभाजन किया और महाभारत की रचना की।",
 "39bb9bea": "धृतराष्ट्र",
 "87ef75c5": "अंधे कुरु राजा, दुर्योधन और उसके निन्यानवे भाइयों के पिता।",
 "540eacb6": "गांधारी",
 "54b106f3": "धृतराष्ट्र की रानी, जिन्होंने जीवन भर अपनी आँखों पर पट्टी बाँधे रखी क्योंकि उनके पति देख नहीं सकते थे।",
 "3505d2d4": "कुंती",
 "d4f5af1a": "कर्ण की और तीन बड़े पांडवों की माता।",
 "d2b8405d": "अर्जुन",
 "1e10148d": "तीसरे पांडव, महान धनुर्धर, श्रीकृष्ण के मित्र, जिन्हें भगवद्गीता का उपदेश मिला।",
 "1fea9dbd": "द्रौपदी",
 "67d388e5": "पांचाल की राजकुमारी, यज्ञ की अग्नि से जन्मी, पाँचों पांडवों की पत्नी।",
 "5a89ec29": "कर्ण",
 "b756af1d": "कुंती के पहले पुत्र, सूर्य से जन्मे, एक सारथी के घर पले, जो अपने ही भाइयों के विरुद्ध लड़े।",
 "353d1afb": "विभीषण",
 "aaca9933": "रावण के छोटे भाई, धर्मात्मा और राम के भक्त। उन्होंने सीता-हरण का विरोध किया और अंत में लंका से निकाल दिए गए।",
});
